import requests, json
def get(url, **kw):
    try:
        r=requests.get(url,timeout=45,**kw)
        return r
    except Exception as e:
        print("ERR",url,repr(e)[:200]); return None

r=get("https://api.github.com/repos/google-deepmind/alphamissense/git/trees/main?recursive=1")
if r is not None and r.status_code==200:
    paths=[t["path"] for t in r.json().get("tree",[])]
    print("google-deepmind/alphamissense paths (first 60):")
    for p in paths[:60]: print("  ",p)
else:
    print("deepmind tree:", getattr(r,'status_code',None))

for repo in ["mtmorgan/AlphaMissenseR","JiMouse/alphamissense","ShaoxunLiu/AlphaMissenseUI"]:
    for br in ["main","master"]:
        rr=get(f"https://raw.githubusercontent.com/{repo}/{br}/README.md")
        if rr is not None and rr.status_code==200:
            print(f"\n===== {repo} README ({br}) =====")
            print(rr.text[:3000])
            break
